// Public website origin explicitly confirmed by the user. Never accept a URL from product data.
const PRODUCT_SHARE_ORIGIN = 'https://ortopedia-cemydi.netlify.app';

export function productShareUrl(slug: string): string | null {
  // Matches the canonical slugs generated by the backend, including its numeric suffixes.
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) return null;
  const url = new URL(`/producto/${encodeURIComponent(slug)}`, PRODUCT_SHARE_ORIGIN);
  if (url.protocol !== 'https:' || url.origin !== PRODUCT_SHARE_ORIGIN) return null;
  return url.href;
}
